import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        ArrayList<Integer> scores = new ArrayList<>();
        scores.add(55);
        scores.add(78);
        scores.add(92);
        scores.add(45);
        scores.add(67);
        scores.add(88);
        int count = 0;
        for (int score : scores) {
            if (score >= 60) {
                count++;
            }
        }
        System.out.println(count);
    }
}
